sealed class Scope(Scope? parent)
{
    readonly Dictionary<string, Symbol> _symbols = new();
    public Scope? Parent { get; } = parent;
    public bool Define(string name, Symbol sym) => _symbols.TryAdd(name, sym);   // dup -> false
    public Symbol? Lookup(string name)                                          // inner -> outer
    {
        for (var s = this; s is not null; s = s.Parent)
            if (s._symbols.TryGetValue(name, out var found)) return found;
        return null;
    }
}

